# patch_v7.py -- Append spatial chapter to v6 docx
from docx import Document
from docx.shared import Pt, Cm, RGBColor
import os

v6 = "output/Hengshan_Report_v6.docx"
out = "output/Hengshan_Report_v7.docx"

if not os.path.exists(v6):
    alt = [f for f in os.listdir("output") if "v6" in f.lower() and f.endswith(".docx")]
    if alt:
        v6 = "output/" + alt[0]

if not os.path.exists(v6):
    print("v6 not found")
    exit(1)

doc = Document(v6)

# Helper
def add_h1(text):
    p = doc.add_paragraph(); r = p.add_run(text); r.bold = True; r.font.size = Pt(16); r.font.color.rgb = RGBColor(0x2D,0x6A,0x4F)
def add_h2(text):
    p = doc.add_paragraph(); r = p.add_run(text); r.bold = True; r.font.size = Pt(13); r.font.color.rgb = RGBColor(0x44,0x44,0x44)
def add_body(text):
    doc.add_paragraph(text)

doc.add_page_break()
add_h1("\u7b2c\u56db\u7ae0 \u7a7a\u95f4\u89c4\u5212")
add_h2("4.1 \u7a7a\u95f4\u53d1\u5c55\u7ed3\u6784\uff1a\u4e00\u5fc3\u00b7\u4e00\u8f74\u00b7\u56db\u533a\u00b7\u591a\u8282\u70b9")
add_body("\u4f9d\u636e\u6a2a\u4e91\u5c71\u5c45\u4e2d\u3001\u56db\u4e2a\u70b9\u4f4d\u73af\u5c71\u5206\u5e03\u7684\u81ea\u7136\u683c\u5c40\uff0c\u6a2a\u5c71\u7684\u7a7a\u95f4\u89c4\u5212\u7ed3\u6784\u4e3a\u4e00\u5fc3\u2014\u2014\u6a2a\u4e91\u5c71\u751f\u6001\u7eff\u5fc3\u3001\u4e00\u8f74\u2014\u2014\u4f58\u5929\u6606\u516c\u8def\u6f2b\u6e38\u4e3b\u8f74\u3001\u56db\u533a\u2014\u2014\u6838\u5fc3\u63a5\u5f85\u533a\u3001\u6587\u5316\u7814\u5b66\u533a\u3001\u6ee8\u6c34\u4f11\u95f2\u533a\u3001\u9ad8\u7aef\u4f4f\u5bbf\u533a\u3001\u591a\u8282\u70b9\u2014\u2014\u9a91\u884c\u505c\u9760\u70b9\u3001\u89c2\u666f\u5e73\u53f0\u3001\u542c\u97f3\u70b9\u3001\u6797\u95f4\u51a5\u60f3\u7ad9\u3002\u56db\u4e2a\u529f\u80fd\u533a\u6cbf\u4f58\u5929\u6606\u516c\u8def\u81ea\u5317\u5411\u5357\u4f9d\u6b21\u5206\u5e03\u3002")

add_h2("4.2 \u56db\u533a\u529f\u80fd\u4e0e\u8303\u56f4")
table = doc.add_table(rows=5, cols=4); table.style = "Light Grid Accent 1"
for i,h in enumerate(["\u529f\u80fd\u533a","\u6838\u5fc3\u7a7a\u95f4","\u4e3b\u5bfc\u529f\u80fd","\u5efa\u7b51\u89c4\u6a21"]):
    table.rows[0].cells[i].text = h
rows = [
    ["\u6838\u5fc3\u63a5\u5f85\u533a","\u6a2a\u5c71\u5927\u9662\u56db\u5408\u9662\u53ca\u5468\u8fb9","\u5230\u8fbe\u7b2c\u4e00\u7ad9\uff0c\u6587\u5316\u5c55\u793a\uff0c\u5e02\u96c6\uff0c\u975e\u9057\u5de5\u574a\uff0c\u6e38\u5ba2\u670d\u52a1","\u7ea61,563\u5e73\u65b9\u7c73\u52a0\u5ead\u9662\u7ea6800\u5e73\u65b9\u7c73"],
    ["\u6587\u5316\u7814\u5b66\u533a","\u6a2a\u5c71\u5c0f\u5b66(\u9ec4\u516c\u671b\u5c0f\u5b66)\u53ca\u5468\u8fb9","\u7814\u5b66\u57fa\u5730\uff0c\u975e\u9057\u4f20\u627f\uff0c\u827a\u672f\u521b\u4f5c\uff0cIP\u6545\u4e8b\u5f15\u64ce","\u7ea6590\u5e73\u65b9\u7c73\u52a0\u5ead\u9662\u7ea61,300\u5e73\u65b9\u7c73(2\u4ea9)"],
    ["\u6ee8\u6c34\u4f11\u95f2\u533a","\u6765\u4e91\u5427(\u9005\u5c71\u5496\u5561)\u53ca\u4e09\u5c94\u8def\u53e3","\u793e\u4ea4\u67a2\u7ebd\uff0c\u5496\u5561\uff0c\u9a91\u884c\uff0c\u5e02\u96c6\uff0c\u591c\u7ecf\u6d4e","\u7ea6815\u5e73\u65b9\u7c73"],
    ["\u9ad8\u7aef\u4f4f\u5bbf\u533a","\u6a2a\u4e91\u5c71\u5c4532\u680b\u53ca\u5357\u5761","\u9ad8\u7aef\u6c11\u5bbf\u96c6\u7fa4\uff0c\u9910\u996e\uff0c\u54c1\u7c73\uff0c\u7597\u6108\uff0c\u661f\u7a7a\u89c2\u6d4b","\u7ea67,881\u5e73\u65b9\u7c73(\u542b\u5730\u4e0b)\uff0c\u603b\u7528\u5730\u7ea615,292\u5e73\u65b9\u7c73"],
]
for ri,row in enumerate(rows):
    for ci,val in enumerate(row): table.rows[ri+1].cells[ci].text = val
doc.add_paragraph()

add_h2("4.3 \u6838\u5fc3\u6e38\u7ebf\u8bbe\u8ba1")
add_body("\u52a8\u7ebf\u4e00\u00b7\u7c73\u4e4b\u65c5\uff08\u7ea64\u516c\u91cc\uff0c\u6b65\u884c\u6216\u9a91\u884c\uff09\uff1a\u6a2a\u5c71\u5927\u9662(\u8d77\u70b9\uff0c\u53d6\u4e94\u611f\u5730\u56fe)\u2192\u5317\u5761\u7a3b\u7530(\u63d2\u79e7\u6216\u6536\u5272\u4f53\u9a8c)\u2192\u78be\u7c73\u574a(\u89c2\u6469\u7a3b\u8c37\u53d8\u767d\u7c73)\u2192\u54c1\u7c73\u5ba4(\u7530\u5757\u54c1\u9274)\u2192\u6a2a\u4e91\u5c71\u5c45(\u7c73\u9152\u5c01\u575b)\u3002\u8bb2\u8ff0\u677e\u6c5f\u5927\u7c73\u4ece\u79cd\u5b50\u5230\u9910\u684c\u7684700\u5e74\u6545\u4e8b\u3002")
add_body("\u52a8\u7ebf\u4e8c\u00b7\u5c71\u4e4b\u884c\uff08\u7ea68\u516c\u91cc\uff0c\u9a91\u884c\uff09\uff1a\u6a2a\u5c71\u5927\u9662\u2192\u6a2a\u5c71\u5c0f\u5b66\u2192\u6765\u4e91\u5427\u2192\u73af\u5c71\u516c\u8def\u2192\u5357\u5761\u89c2\u666f\u53f0\u2192\u6a2a\u4e91\u5c71\u5c45\u2192\u8fd4\u56de\u3002\u6cbf\u90144\u4e2a\u592a\u9633\u80fdLED\u505c\u9760\u70b9\u3002\u591c\u9a91\u7248\u540c\u7ebf\u2014\u2014LED\u8def\u6807\u6307\u5f15\uff0c\u5de6\u4fa7\u6a2a\u4e91\u5c71\u9ed1\u8272\u526a\u5f71\uff0c\u53f3\u4fa7\u6f06\u9ed1\u7a3b\u7530\u3002")
add_body("\u52a8\u7ebf\u4e09\u00b7\u6797\u4e4b\u6108\uff08\u7ea62\u516c\u91cc\uff0c\u6b65\u884c\uff09\uff1a\u6a2a\u5c71\u5c0f\u5b66\u2192\u7af9\u6797\u96fe\u5883\u2192\u8d64\u811a\u6b65\u9053(200\u7c73\uff0c\u788e\u77f3\u2192\u8349\u5730\u2192\u6ce5\u571f\u2192\u6eaa\u6c34)\u2192\u6797\u95f4\u51a5\u60f3\u7ad9(5\u5ea7)\u2192\u58f0\u7597\u5ba4\u2192\u8fd4\u56de\u3002\u4e0d\u8bbe\u8def\u706f\u2014\u2014\u53ea\u6709\u5730\u9762\u5fae\u5149\u6307\u5f15\u3002")

add_h2("4.4 \u5efa\u7b51\u98ce\u8c8c\u4e0e\u505c\u8f66\u7ec4\u7ec7")
add_body("\u6838\u5fc3\u539f\u5219\uff1a\u5e73\u6de1\u5929\u771f(\u9ec4\u516c\u671b\u753b\u8bba\u6838\u5fc3)\u2014\u2014\u4e0d\u8ffd\u6c42\u5962\u534e\uff0c\u4e0d\u4eff\u53e4\u3002\u6750\u6599\uff1a\u672c\u5730\u77f3\u6750\uff0c\u5938\u571f\uff0c\u70e7\u6749\u677f\uff0c\u5927\u5e45\u73bb\u7483\u3002\u8272\u5f69\u53d6\u81ea\u5c71\u6797\uff1a\u6df1\u68d5\uff0c\u7070\u7eff\uff0c\u7c73\u767d\u3002\u706f\u5149\u5168\u5c0f\u4e8e3000K\uff0c\u5168\u90e8\u5411\u4e0b\u7167\u5c04\u3002\u56db\u4e2a\u70b9\u4f4d\u505c\u8f66\u573a\u603b\u5bb9\u91cf\u7ea6127\u8f86(\u5927\u966220\u52a0\u5c0f\u5b6612\u52a0\u6765\u4e91\u542715\u52a0\u5c71\u5c4580)\u3002\u6751\u57df\u5185\u9650\u901f30\u516c\u91cc\u6bcf\u5c0f\u65f6\uff0c\u73af\u5c71\u8def\u6162\u884c\u4f18\u5148\u3002")

doc.save(out)
print("v7 OK: " + str(os.path.getsize(out) // 1024) + " KB")
